<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { listAudit,type AuditItem } from '@/api/operations'
const query=reactive({adminUserId:'',action:'',objectType:'',objectId:'',start:'',end:'',page:1,pageSize:20}),items=ref<AuditItem[]>([]),total=ref(0),loading=ref(false),selected=ref<AuditItem>(),visible=ref(false)
const diff=computed(()=>{const before=selected.value?.beforeJson || {},after=selected.value?.afterJson || {};return [...new Set([...Object.keys(before),...Object.keys(after)])].map(key=>({key,before:JSON.stringify(before[key]) ?? '—',after:JSON.stringify(after[key]) ?? '—',changed:JSON.stringify(before[key])!==JSON.stringify(after[key])}))})
async function load(){loading.value=true;try{const data=await listAudit(query);items.value=data.list;total.value=data.total}finally{loading.value=false}}
async function search(){query.page=1;await load()}
function open(row:AuditItem){selected.value=row;visible.value=true}
function rowStyle({row}:{row:{changed:boolean}}){return row.changed?{background:'#eef8f3'}:{}}
onMounted(load)
</script>
<template><el-card shadow="never"><el-form inline><el-form-item><el-input v-model="query.adminUserId" placeholder="管理员ID" style="width:120px"/></el-form-item><el-form-item><el-input v-model="query.action" placeholder="动作，例如 chat.export"/></el-form-item><el-form-item><el-input v-model="query.objectType" placeholder="对象类型" style="width:120px"/></el-form-item><el-form-item><el-input v-model="query.objectId" placeholder="对象ID" style="width:120px"/></el-form-item><el-form-item><el-date-picker v-model="query.start" value-format="YYYY-MM-DD" placeholder="开始日期" style="width:145px"/></el-form-item><el-form-item><el-date-picker v-model="query.end" value-format="YYYY-MM-DD" placeholder="结束日期" style="width:145px"/></el-form-item><el-button type="primary" @click="search">查询</el-button></el-form><el-alert title="审计由服务层移除凭据和敏感正文，前后值仅展示脱敏快照。" :closable="false" style="margin-bottom:16px"/><el-table v-loading="loading" :data="items"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="username" label="操作人"/><el-table-column prop="action" label="动作" min-width="180"/><el-table-column prop="objectType" label="对象类型"/><el-table-column prop="objectId" label="对象ID"/><el-table-column prop="createdAt" label="时间" min-width="170"/><el-table-column label="改动"><template #default="{row}"><el-button link @click="open(row)">查看 Diff</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="search" style="margin-top:20px"/></el-card><el-drawer v-model="visible" title="脱敏前后 Diff" size="800px"><el-table :data="diff" :row-style="rowStyle"><el-table-column prop="key" label="字段" width="145"/><el-table-column prop="before" label="修改前" min-width="250"/><el-table-column prop="after" label="修改后" min-width="250"/></el-table></el-drawer></template>
